@Override public void getPaymentAccountForm(GetPaymentAccountFormRequest req, StreamObserver<GetPaymentAccountFormReply> responseObserver){
    try {
        var paymentAccountFormJson = coreApi.getPaymentAccountForm(req.getPaymentMethodId());
        var reply = GetPaymentAccountFormReply.newBuilder().setPaymentAccountFormJson(paymentAccountFormJson).build();
        responseObserver.onNext(reply);
        responseObserver.onCompleted();
    } catch (RuntimeException e) {
        responseObserver.onError(e);
    }
}
